"""Offline, conservative cost reservations for a shared text-only budget."""

from __future__ import annotations

import json
from contextlib import contextmanager
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path

try:
    import fcntl
except ImportError:  # No safe cross-process locking on this platform.
    fcntl = None

from voice_agent.utils.common import write_json


class BudgetError(RuntimeError):
    """The ledger is invalid, unavailable, or cannot authorize a request."""


def _money(value):
    if not isinstance(value, str):
        raise BudgetError("Money must be a decimal string")
    try:
        amount = Decimal(value)
    except InvalidOperation as exc:
        raise BudgetError("Invalid money") from exc
    if not amount.is_finite() or amount < 0:
        raise BudgetError("Money must be finite and nonnegative")
    return amount


def _int(value, minimum, maximum=None):
    if type(value) is not int or value < minimum or (maximum is not None and value > maximum):
        raise BudgetError("Invalid integer limit or token count")
    return value


def _price(model):
    if not isinstance(model, dict):
        raise BudgetError("Invalid model catalog entry")
    try:
        return (_money(model["input_usd_per_million"]),
                _money(model["output_usd_per_million"]),
                _int(model["max_input_tokens"], 1))
    except KeyError as exc:
        raise BudgetError("Incomplete model catalog entry") from exc


def max_cost_usd(model: str, max_output_tokens: int, catalog: dict) -> Decimal:
    """Price the entire input context and requested output at uncached rates."""
    try:
        input_price, output_price, max_input = _price(catalog[model])
        _int(max_output_tokens, 1, 1200)
        with localcontext() as ctx:
            prices = (input_price, output_price)
            ctx.prec = max(28, max(p.adjusted() for p in prices) - min(p.as_tuple().exponent for p in prices)
                           + len(str(max_input)) + len(str(max_output_tokens)) + 12)
            return (input_price * max_input + output_price * max_output_tokens) / Decimal(1_000_000)
    except (KeyError, TypeError) as exc:
        raise BudgetError("Unknown model") from exc


def _usage_cost(usage, model, max_output):
    if not isinstance(usage, dict):
        raise BudgetError("Missing usage")
    input_price, output_price, max_input = _price(model)
    try:
        prompt = _int(usage["prompt_tokens"], 0, max_input)
        completion = _int(usage["completion_tokens"], 0, max_output)
    except KeyError as exc:
        raise BudgetError("Missing usage tokens") from exc
    return (input_price * prompt + output_price * completion) / Decimal(1_000_000)


def _limits(batch):
    limits = batch.get("limits")
    if not isinstance(limits, dict):
        raise BudgetError("Missing limits")
    for name, low, high in (("max_requests", 1, 100), ("max_output_tokens", 1, 1200),
                            ("max_request_bytes", 1, 256000), ("max_retries", 0, 1),
                            ("max_caller_turns", 1, 12), ("max_tool_steps", 1, 8),
                            ("max_audio_seconds", 0, 0)):
        if name not in limits:
            raise BudgetError("Missing limit: " + name)
        _int(limits[name], low, high)
    return limits


class CostLedger:
    def __init__(self, path: Path, batch_id: str):
        self.path = Path(path)
        self.batch_id = batch_id

    @contextmanager
    def _locked(self):
        if fcntl is None:
            raise BudgetError("Cross-process locking unavailable")
        try:
            with self.path.with_name(self.path.name + ".lock").open("a") as lock:
                fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
                try:
                    with localcontext() as ctx:
                        ctx.prec = 256
                        yield
                finally:
                    fcntl.flock(lock.fileno(), fcntl.LOCK_UN)
        except (OSError, InvalidOperation, OverflowError) as exc:
            raise BudgetError("Ledger lock or I/O failed") from exc

    def _load(self):
        try:
            with self.path.open(encoding="utf-8") as handle:
                data = json.load(handle)
            if not isinstance(data, dict) or not isinstance(data["models"], dict) or not isinstance(data["allocations"], dict) or not isinstance(data["batches"], list):
                raise BudgetError("Invalid ledger")
            credit = _money(data["starting_credit_usd"])
            allocations = {name: _money(value) for name, value in data["allocations"].items()}
            batches = data["batches"]
            if any(not isinstance(batch, dict) for batch in batches):
                raise BudgetError("Invalid batch")
            ids = [batch.get("id") for batch in batches]
            if any(not isinstance(item, str) or not item for item in ids) or len(set(ids)) != len(ids):
                raise BudgetError("Invalid batch IDs")
            matches = [batch for batch in batches if batch["id"] == self.batch_id]
            if len(matches) != 1:
                raise BudgetError("Batch not found")
            target = matches[0]
            if target.get("approved") is not True or not isinstance(target.get("approval_reference"), str) or not target["approval_reference"].strip():
                raise BudgetError("Batch is not approved")
            for batch in batches:
                if batch.get("allocation") not in allocations:
                    raise BudgetError("Unknown allocation")
                ceiling = _money(batch["max_cost_usd"])
                if ceiling > allocations[batch["allocation"]] or ceiling > credit:
                    raise BudgetError("Batch ceiling exceeds allocation or credit")
                if batch.get("model") not in data["models"]:
                    raise BudgetError("Unknown model")
                _price(data["models"][batch["model"]])
                _limits(batch)
                if not isinstance(batch.get("requests"), list):
                    raise BudgetError("Invalid requests")
            return data, target, credit, allocations
        except (OSError, ValueError, KeyError, TypeError) as exc:
            raise BudgetError("Cannot read valid ledger") from exc

    def _totals(self, data, credit):
        recorded = Decimal(0)
        held = Decimal(0)
        batch_costs = {}
        allocation_costs = {name: Decimal(0) for name in data["allocations"]}
        for batch in data["batches"]:
            subtotal = Decimal(0)
            seen = set()
            for request in batch["requests"]:
                if not isinstance(request, dict) or not isinstance(request.get("id"), str) or request["id"] in seen:
                    raise BudgetError("Invalid request entry")
                seen.add(request["id"])
                reservation = _money(request.get("reserve_max_cost_usd"))
                # Never trust a stored reservation smaller than the full-context price.
                maximum = _int(request.get("max_output_tokens"), 1, batch["limits"]["max_output_tokens"])
                required = max_cost_usd(batch["model"], maximum, data["models"])
                if reservation < required:
                    raise BudgetError("Reservation below full-context cost")
                cost = reservation
                if request.get("status") == "reconciled":
                    try:
                        cost = _usage_cost(request.get("usage"), data["models"][batch["model"]], maximum)
                    except BudgetError:
                        held += reservation
                    else:
                        recorded += cost
                else:
                    held += reservation
                subtotal += cost
            batch_costs[batch["id"]] = subtotal
            allocation_costs[batch["allocation"]] += subtotal
        data["totals"] = {"recorded_usage_usd": str(recorded), "unreconciled_max_usd": str(held),
                          "remaining_credit_estimate_usd": str(credit - recorded - held)}
        return batch_costs, allocation_costs, recorded + held

    @property
    def limits(self):
        with self._locked():
            _, batch, _, _ = self._load()
            return dict(_limits(batch))

    def reserve(self, model: str, max_output_tokens: int, request_bytes: int, role: str, attempt: int) -> str:
        with self._locked():
            data, batch, credit, allocations = self._load()
            limits = _limits(batch)
            if batch.get("halted", False) is not False:
                raise BudgetError("Batch is halted")
            if model != batch["model"] or role not in ("AGENT", "SIMULATOR", "JUDGE"):
                raise BudgetError("Model or role not permitted")
            _int(max_output_tokens, 1, limits["max_output_tokens"])
            _int(request_bytes, 1, limits["max_request_bytes"])
            _int(attempt, 0, limits["max_retries"])
            if len(batch["requests"]) >= limits["max_requests"]:
                raise BudgetError("Request count exceeded")
            batch_costs, allocation_costs, total = self._totals(data, credit)
            cost = max_cost_usd(model, max_output_tokens, data["models"])
            if (batch_costs[batch["id"]] + cost > _money(batch["max_cost_usd"])
                    or allocation_costs[batch["allocation"]] + cost > allocations[batch["allocation"]]
                    or total + cost > credit):
                raise BudgetError("Budget exceeded")
            request_id = f"{self.batch_id}-{len(batch['requests']) + 1}"
            if any(r["id"] == request_id for r in batch["requests"]):
                raise BudgetError("Duplicate request ID")
            batch["requests"].append({"id": request_id, "model": model, "role": role,
                                      "attempt": attempt, "timestamp": datetime.now(timezone.utc).isoformat(),
                                      "max_output_tokens": max_output_tokens, "request_bytes": request_bytes,
                                      "reserve_max_cost_usd": str(cost), "status": "pending"})
            self._totals(data, credit)
            write_json(self.path, data)
            return request_id

    def _finish(self, request_id, usage=None, error_type=None):
        with self._locked():
            data, batch, credit, _ = self._load()
            self._totals(data, credit)
            matches = [request for request in batch["requests"] if request["id"] == request_id]
            if len(matches) != 1 or matches[0].get("status") != "pending":
                raise BudgetError("Request not pending")
            request = matches[0]
            error = None
            if error_type is not None:
                request.update(status="failed", error_type=error_type)
            else:
                try:
                    _usage_cost(usage, data["models"][batch["model"]], request["max_output_tokens"])
                except BudgetError as exc:
                    request.update(status="failed", error_type="invalid_usage")
                    batch.update(halted=True, halt_reason="invalid_usage")
                    error = exc
                else:
                    request.update(status="reconciled", usage={"prompt_tokens": usage["prompt_tokens"],
                                                               "completion_tokens": usage["completion_tokens"]})
            self._totals(data, credit)
            write_json(self.path, data)
            if error:
                raise error

    def halt(self, reason: str) -> None:
        if not isinstance(reason, str) or not reason or len(reason) > 100 or not all(c.isalnum() or c in "_-" for c in reason):
            raise BudgetError("Invalid halt reason")
        with self._locked():
            data, batch, credit, _ = self._load()
            batch.update(halted=True, halt_reason=reason)
            self._totals(data, credit)
            write_json(self.path, data)

    def reconcile(self, request_id: str, usage: dict) -> None:
        self._finish(request_id, usage=usage)

    def fail(self, request_id: str, error_type: str) -> None:
        if not isinstance(error_type, str) or not error_type or len(error_type) > 100 or not all(c.isalnum() or c in "_-" for c in error_type):
            raise BudgetError("Invalid error type")
        self._finish(request_id, error_type=error_type)

"""Provider-neutral LLM client with tool calling (standard library HTTP only).

Two wire formats cover every provider the team considered:

* ``OpenAICompatibleClient``: OpenAI, Groq and Ollama all expose the same
  ``/chat/completions`` API with tool calls, so one adapter serves all three.
* ``AnthropicClient``: Anthropic's ``/v1/messages`` API.

Internally every message uses one neutral format::

    {"role": "system" | "user" | "assistant" | "tool", "content": str,
     "tool_calls": [{"id": str, "name": str, "arguments": dict}],   # assistant only
     "tool_call_id": str}                                          # tool only

so the agent, simulator and judge never depend on a provider. The provider is
picked with environment variables (see .env.example), which keeps API keys out
of code and lets the paid provider replace the free local one without edits.
"""

from __future__ import annotations

import json
import os
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field

from voice_agent.models.budget import BudgetError, CostLedger

PROVIDERS = {
    # name: (wire format, default base URL, API key variable)
    "openai": ("openai", "https://api.openai.com/v1", "OPENAI_API_KEY"),
    "groq": ("openai", "https://api.groq.com/openai/v1", "GROQ_API_KEY"),
    "ollama": ("openai", "http://localhost:11434/v1", None),
    "anthropic": ("anthropic", "https://api.anthropic.com/v1", "ANTHROPIC_API_KEY"),
}


@dataclass
class Completion:
    content: str
    tool_calls: list = field(default_factory=list)
    usage: dict = field(default_factory=dict)
    latency_s: float = 0.0


class LLMError(RuntimeError):
    pass


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise LLMError("Model HTTP redirects are disabled")


_HTTP = urllib.request.build_opener(_NoRedirect())
LOCAL_URLS = {f"http://{host}:11434/v1/chat/completions" for host in ("localhost", "127.0.0.1")}
OPENAI_URL = "https://api.openai.com/v1/chat/completions"


def _post(url: str, payload: dict, headers: dict, timeout: float, retries: int | None = None,
          *, budget: CostLedger | None = None, role: str = "AGENT") -> dict:
    local = url in LOCAL_URLS
    if not local and (url != OPENAI_URL or budget is None):
        raise BudgetError("Remote calls require an approved direct-OpenAI text batch; other providers/audio are blocked")
    if local and budget is not None:
        raise BudgetError("A paid OpenAI batch cannot be used for a local-model request")
    token_key = "max_tokens" if local else "max_completion_tokens"
    cap = payload.get(token_key)
    if type(cap) is not int or not 1 <= cap <= 1200:
        raise BudgetError("Output token cap must be an integer from 1 to 1200")
    allowed = {"model", "messages", "temperature", token_key, "tools", "response_format"}
    allowed |= {"reasoning_effort"} if local else {"service_tier", "n"}
    if set(payload) - allowed:
        raise BudgetError("Only bounded text Chat Completions fields are allowed")
    if not local and (payload.get("service_tier") != "default" or payload.get("n") != 1):
        raise BudgetError("Paid requests require standard tier and n=1")
    if not isinstance(payload.get("messages"), list) or any(
            not isinstance(m, dict) or set(m) - {"role", "content", "tool_calls", "tool_call_id"}
            or not (isinstance(m.get("content"), str) or m.get("content") is None)
            for m in payload["messages"]):
        raise BudgetError("Only text messages are allowed; audio and images are blocked")
    if any(not isinstance(t, dict) or t.get("type") != "function" for t in payload.get("tools", [])):
        raise BudgetError("Only local function tools are allowed, not separately billed hosted tools")
    body = json.dumps(payload).encode("utf-8")
    if len(body) > 256000:
        raise BudgetError("Request exceeds the hard 256000-byte text limit")
    retry_limit = budget.limits["max_retries"] if budget is not None else 0
    retries = retry_limit if retries is None else retries
    if type(retries) is not int or not 0 <= retries <= retry_limit:
        raise BudgetError("Retry count exceeds batch limits")
    for attempt in range(retries + 1):
        reservation = (budget.reserve(payload["model"], cap, len(body), role, attempt)
                       if budget is not None else None)
        request = urllib.request.Request(url, data=body, method="POST",
                                         headers={"Content-Type": "application/json", **headers})
        try:
            with _HTTP.open(request, timeout=min(timeout, 30.0)) as response:
                data = json.loads(response.read().decode("utf-8"))
            if budget is not None:
                if data.get("service_tier") != "default" or data.get("model") != payload["model"]:
                    budget.fail(reservation, "UnexpectedModelOrServiceTier")
                    budget.halt("unexpected_model_or_service_tier")
                    raise BudgetError("Unexpected response model/service tier; batch halted")
                budget.reconcile(reservation, data.get("usage"))
            return data
        except BudgetError:
            raise
        except Exception as err:
            if budget is not None:
                budget.fail(reservation, type(err).__name__)
            retryable = (isinstance(err, (urllib.error.URLError, TimeoutError))
                         and not isinstance(err, urllib.error.HTTPError)) or (
                isinstance(err, urllib.error.HTTPError) and err.code in (429, 500, 502, 503, 529))
            if retryable and attempt < retries:
                time.sleep(2 ** attempt)
                continue
            raise LLMError(f"Model request failed ({type(err).__name__}); uncertain usage remains reserved") from None
    raise LLMError("unreachable")


class OpenAICompatibleClient:
    def __init__(self, model: str, base_url: str, api_key: str | None = None,
                 timeout: float = 30.0, extra: dict | None = None,
                 budget: CostLedger | None = None, role: str = "AGENT"):
        self.model, self.base_url, self.api_key = model, base_url.rstrip("/"), api_key
        self.timeout, self.extra = timeout, extra or {}
        self.budget, self.role = budget, role

    @staticmethod
    def to_wire(messages: list[dict]) -> list[dict]:
        wire = []
        for m in messages:
            if m["role"] == "assistant" and m.get("tool_calls"):
                wire.append({"role": "assistant", "content": m.get("content") or None,
                             "tool_calls": [{"id": c["id"], "type": "function",
                                             "function": {"name": c["name"],
                                                          "arguments": json.dumps(c["arguments"])}}
                                            for c in m["tool_calls"]]})
            elif m["role"] == "tool":
                wire.append({"role": "tool", "tool_call_id": m["tool_call_id"], "content": m["content"]})
            else:
                wire.append({"role": m["role"], "content": m["content"]})
        return wire

    @staticmethod
    def from_wire(data: dict) -> Completion:
        message = data["choices"][0]["message"]
        calls = []
        for i, c in enumerate(message.get("tool_calls") or []):
            raw = c["function"].get("arguments") or "{}"
            try:
                args = json.loads(raw) if isinstance(raw, str) else raw
            except json.JSONDecodeError:
                args = {"_unparsed": raw}
            calls.append({"id": c.get("id") or f"call_{i}", "name": c["function"]["name"], "arguments": args})
        usage = data.get("usage") or {}
        return Completion(content=message.get("content") or "", tool_calls=calls,
                          usage={"input_tokens": usage.get("prompt_tokens", 0),
                                 "output_tokens": usage.get("completion_tokens", 0)})

    def complete(self, messages, tools=None, temperature=0.0, max_tokens=800, json_mode=False) -> Completion:
        direct_openai = self.base_url == "https://api.openai.com/v1"
        token_key = "max_completion_tokens" if direct_openai else "max_tokens"
        payload = {"model": self.model, "messages": self.to_wire(messages),
                   "temperature": temperature, token_key: max_tokens, **self.extra}
        if direct_openai:
            payload.update(service_tier="default", n=1)
        if tools:
            payload["tools"] = [{"type": "function", "function": t} for t in tools]
        if json_mode:
            payload["response_format"] = {"type": "json_object"}
        headers = {"Authorization": f"Bearer {self.api_key}"} if self.api_key else {}
        start = time.perf_counter()
        result = self.from_wire(_post(f"{self.base_url}/chat/completions", payload, headers, self.timeout,
                                      budget=self.budget, role=self.role))
        result.latency_s = time.perf_counter() - start
        return result


class AnthropicClient:
    def __init__(self, model: str, api_key: str, base_url: str = "https://api.anthropic.com/v1",
                 timeout: float = 180.0):
        self.model, self.api_key, self.base_url, self.timeout = model, api_key, base_url.rstrip("/"), timeout

    @staticmethod
    def to_wire(messages: list[dict]) -> tuple[str, list[dict]]:
        system = "\n\n".join(m["content"] for m in messages if m["role"] == "system")
        wire: list[dict] = []
        for m in messages:
            if m["role"] == "system":
                continue
            if m["role"] == "assistant":
                blocks = [{"type": "text", "text": m["content"]}] if m.get("content") else []
                blocks += [{"type": "tool_use", "id": c["id"], "name": c["name"], "input": c["arguments"]}
                           for c in m.get("tool_calls") or []]
                wire.append({"role": "assistant", "content": blocks or [{"type": "text", "text": "..."}]})
            elif m["role"] == "tool":
                block = {"type": "tool_result", "tool_use_id": m["tool_call_id"], "content": m["content"]}
                if wire and wire[-1]["role"] == "user" and isinstance(wire[-1]["content"], list) \
                        and wire[-1]["content"] and wire[-1]["content"][0].get("type") == "tool_result":
                    wire[-1]["content"].append(block)  # results of parallel calls share one turn
                else:
                    wire.append({"role": "user", "content": [block]})
            else:
                wire.append({"role": "user", "content": m["content"]})
        return system, wire

    @staticmethod
    def from_wire(data: dict) -> Completion:
        text = "".join(b.get("text", "") for b in data.get("content", []) if b["type"] == "text")
        calls = [{"id": b["id"], "name": b["name"], "arguments": b.get("input") or {}}
                 for b in data.get("content", []) if b["type"] == "tool_use"]
        usage = data.get("usage") or {}
        return Completion(content=text, tool_calls=calls,
                          usage={"input_tokens": usage.get("input_tokens", 0),
                                 "output_tokens": usage.get("output_tokens", 0)})

    def complete(self, messages, tools=None, temperature=0.0, max_tokens=800, json_mode=False) -> Completion:
        system, wire = self.to_wire(messages)
        payload = {"model": self.model, "system": system, "messages": wire,
                   "temperature": temperature, "max_tokens": max_tokens}
        if tools:
            payload["tools"] = [{"name": t["name"], "description": t["description"],
                                 "input_schema": t["parameters"]} for t in tools]
        headers = {"x-api-key": self.api_key, "anthropic-version": "2023-06-01"}
        start = time.perf_counter()
        result = self.from_wire(_post(f"{self.base_url}/messages", payload, headers, self.timeout))
        result.latency_s = time.perf_counter() - start
        return result


def make_client(role: str = "AGENT", budget: CostLedger | None = None):
    """Build a client from env vars, e.g. AGENT_PROVIDER / AGENT_MODEL.

    Falls back to LLM_PROVIDER / LLM_MODEL so one setting can drive the agent,
    simulator and judge. Roles: AGENT, SIMULATOR, JUDGE.
    """
    provider = (os.getenv(f"{role}_PROVIDER") or os.getenv("LLM_PROVIDER") or "").lower()
    model = os.getenv(f"{role}_MODEL") or os.getenv("LLM_MODEL")
    if provider not in PROVIDERS or not model:
        raise LLMError(f"Set LLM_PROVIDER ({'/'.join(PROVIDERS)}) and LLM_MODEL (or {role}_*) in .env")
    wire, default_url, key_var = PROVIDERS[provider]
    api_key = os.getenv(key_var) if key_var else None
    if key_var and not api_key:
        raise LLMError(f"{key_var} is not set")
    base_url = os.getenv(f"{provider.upper()}_BASE_URL") or default_url
    if provider == "ollama" and not base_url.rstrip("/").endswith("/v1"):
        base_url = base_url.rstrip("/") + "/v1"
    if wire == "anthropic":
        return AnthropicClient(model, api_key, base_url)
    extra = {"reasoning_effort": "none"} if provider == "ollama" else {}
    return OpenAICompatibleClient(model, base_url, api_key, extra=extra, budget=budget, role=role)

"""Offline, conservative cost reservations for a shared text-only budget."""

from __future__ import annotations

import json
import os
from contextlib import contextmanager
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path

try:
    import fcntl
except ImportError:  # No safe cross-process locking on this platform.
    fcntl = None

from voice_agent.utils.common import write_json


class BudgetError(RuntimeError):
    """The ledger is invalid, unavailable, or cannot authorize a request."""


def _money(value):
    if not isinstance(value, str):
        raise BudgetError("Money must be a decimal string")
    try:
        amount = Decimal(value)
    except InvalidOperation as exc:
        raise BudgetError("Invalid money") from exc
    if not amount.is_finite() or amount < 0:
        raise BudgetError("Money must be finite and nonnegative")
    return amount


def _int(value, minimum, maximum=None):
    if type(value) is not int or value < minimum or (maximum is not None and value > maximum):
        raise BudgetError("Invalid integer limit or token count")
    return value


def _price(model):
    if not isinstance(model, dict):
        raise BudgetError("Invalid model catalog entry")
    try:
        return (_money(model["input_usd_per_million"]),
                _money(model["output_usd_per_million"]),
                _int(model["max_input_tokens"], 1))
    except KeyError as exc:
        raise BudgetError("Incomplete model catalog entry") from exc


def max_cost_usd(model: str, max_output_tokens: int, catalog: dict) -> Decimal:
    """Price the entire input context and requested output at uncached rates."""
    try:
        input_price, output_price, max_input = _price(catalog[model])
        _int(max_output_tokens, 1, 1200)
        with localcontext() as ctx:
            prices = (input_price, output_price)
            ctx.prec = max(28, max(p.adjusted() for p in prices) - min(p.as_tuple().exponent for p in prices)
                           + len(str(max_input)) + len(str(max_output_tokens)) + 12)
            return (input_price * max_input + output_price * max_output_tokens) / Decimal(1_000_000)
    except (KeyError, TypeError) as exc:
        raise BudgetError("Unknown model") from exc


def _usage_cost(usage, model, max_output):
    if not isinstance(usage, dict):
        raise BudgetError("Missing usage")
    input_price, output_price, max_input = _price(model)
    try:
        prompt = _int(usage["prompt_tokens"], 0, max_input)
        completion = _int(usage["completion_tokens"], 0, max_output)
    except KeyError as exc:
        raise BudgetError("Missing usage tokens") from exc
    return (input_price * prompt + output_price * completion) / Decimal(1_000_000)


def _limits(batch):
    limits = batch.get("limits")
    if not isinstance(limits, dict):
        raise BudgetError("Missing limits")
    for name, low, high in (("max_requests", 1, 100), ("max_output_tokens", 1, 1200),
                            ("max_request_bytes", 1, 256000), ("max_retries", 0, 1),
                            ("max_caller_turns", 1, 12), ("max_tool_steps", 1, 8),
                            ("max_audio_seconds", 0, 0)):
        if name not in limits:
            raise BudgetError("Missing limit: " + name)
        _int(limits[name], low, high)
    return limits


class CostLedger:
    def __init__(self, path: Path, batch_id: str):
        self.path = Path(path)
        self.batch_id = batch_id

    @contextmanager
    def _locked(self):
        if fcntl is None:
            raise BudgetError("Cross-process locking unavailable")
        try:
            with self.path.with_name(self.path.name + ".lock").open("a") as lock:
                fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
                try:
                    with localcontext() as ctx:
                        ctx.prec = 256
                        yield
                finally:
                    fcntl.flock(lock.fileno(), fcntl.LOCK_UN)
        except (OSError, InvalidOperation, OverflowError) as exc:
            raise BudgetError("Ledger lock or I/O failed") from exc

    def _save(self, data):
        write_json(self.path, data)
        # A request must not leave the machine before its reservation is durable.
        with self.path.open("rb") as handle:
            os.fsync(handle.fileno())
        directory = os.open(self.path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)

    def _load(self):
        try:
            with self.path.open(encoding="utf-8") as handle:
                data = json.load(handle)
            if not isinstance(data, dict) or not isinstance(data["models"], dict) or not isinstance(data["allocations"], dict) or not isinstance(data["batches"], list):
                raise BudgetError("Invalid ledger")
            credit = _money(data["starting_credit_usd"])
            allocations = {name: _money(value) for name, value in data["allocations"].items()}
            batches = data["batches"]
            if any(not isinstance(batch, dict) for batch in batches):
                raise BudgetError("Invalid batch")
            ids = [batch.get("id") for batch in batches]
            if any(not isinstance(item, str) or not item for item in ids) or len(set(ids)) != len(ids):
                raise BudgetError("Invalid batch IDs")
            matches = [batch for batch in batches if batch["id"] == self.batch_id]
            if len(matches) != 1:
                raise BudgetError("Batch not found")
            target = matches[0]
            if target.get("approved") is not True or not isinstance(target.get("approval_reference"), str) or not target["approval_reference"].strip():
                raise BudgetError("Batch is not approved")
            for batch in batches:
                if batch.get("allocation") not in allocations:
                    raise BudgetError("Unknown allocation")
                ceiling = _money(batch["max_cost_usd"])
                if ceiling > allocations[batch["allocation"]] or ceiling > credit:
                    raise BudgetError("Batch ceiling exceeds allocation or credit")
                if batch.get("model") not in data["models"]:
                    raise BudgetError("Unknown model")
                _price(data["models"][batch["model"]])
                _limits(batch)
                if not isinstance(batch.get("requests"), list):
                    raise BudgetError("Invalid requests")
            return data, target, credit, allocations
        except (OSError, ValueError, KeyError, TypeError) as exc:
            raise BudgetError("Cannot read valid ledger") from exc

    def _totals(self, data, credit):
        recorded = Decimal(0)
        held = Decimal(0)
        batch_costs = {}
        allocation_costs = {name: Decimal(0) for name in data["allocations"]}
        for batch in data["batches"]:
            subtotal = Decimal(0)
            seen = set()
            for request in batch["requests"]:
                if not isinstance(request, dict) or not isinstance(request.get("id"), str) or request["id"] in seen:
                    raise BudgetError("Invalid request entry")
                seen.add(request["id"])
                reservation = _money(request.get("reserve_max_cost_usd"))
                # Never trust a stored reservation smaller than the full-context price.
                maximum = _int(request.get("max_output_tokens"), 1, batch["limits"]["max_output_tokens"])
                required = max_cost_usd(batch["model"], maximum, data["models"])
                if reservation < required:
                    raise BudgetError("Reservation below full-context cost")
                cost = reservation
                if request.get("status") == "reconciled":
                    try:
                        cost = _usage_cost(request.get("usage"), data["models"][batch["model"]], maximum)
                    except BudgetError:
                        held += reservation
                    else:
                        recorded += cost
                else:
                    held += reservation
                subtotal += cost
            batch_costs[batch["id"]] = subtotal
            allocation_costs[batch["allocation"]] += subtotal
        data["totals"] = {"recorded_usage_usd": str(recorded), "unreconciled_max_usd": str(held),
                          "remaining_credit_estimate_usd": str(credit - recorded - held)}
        return batch_costs, allocation_costs, recorded + held

    @property
    def limits(self):
        with self._locked():
            _, batch, _, _ = self._load()
            return dict(_limits(batch))

    def reserve(self, model: str, max_output_tokens: int, request_bytes: int, role: str, attempt: int) -> str:
        with self._locked():
            data, batch, credit, allocations = self._load()
            limits = _limits(batch)
            if batch.get("halted", False) is not False:
                raise BudgetError("Batch is halted")
            if model != batch["model"] or role not in ("AGENT", "SIMULATOR", "JUDGE"):
                raise BudgetError("Model or role not permitted")
            _int(max_output_tokens, 1, limits["max_output_tokens"])
            _int(request_bytes, 1, limits["max_request_bytes"])
            _int(attempt, 0, limits["max_retries"])
            if len(batch["requests"]) >= limits["max_requests"]:
                raise BudgetError("Request count exceeded")
            batch_costs, allocation_costs, total = self._totals(data, credit)
            cost = max_cost_usd(model, max_output_tokens, data["models"])
            if (batch_costs[batch["id"]] + cost > _money(batch["max_cost_usd"])
                    or allocation_costs[batch["allocation"]] + cost > allocations[batch["allocation"]]
                    or total + cost > credit):
                raise BudgetError("Budget exceeded")
            request_id = f"{self.batch_id}-{len(batch['requests']) + 1}"
            if any(r["id"] == request_id for r in batch["requests"]):
                raise BudgetError("Duplicate request ID")
            batch["requests"].append({"id": request_id, "model": model, "role": role,
                                      "attempt": attempt, "timestamp": datetime.now(timezone.utc).isoformat(),
                                      "max_output_tokens": max_output_tokens, "request_bytes": request_bytes,
                                      "reserve_max_cost_usd": str(cost), "status": "pending"})
            self._totals(data, credit)
            self._save(data)
            return request_id

    def _finish(self, request_id, usage=None, error_type=None, halt=False):
        with self._locked():
            data, batch, credit, _ = self._load()
            self._totals(data, credit)
            matches = [request for request in batch["requests"] if request["id"] == request_id]
            if len(matches) != 1 or matches[0].get("status") != "pending":
                raise BudgetError("Request not pending")
            request = matches[0]
            error = None
            if error_type is not None:
                request.update(status="failed", error_type=error_type)
                if halt:
                    batch.update(halted=True, halt_reason=error_type)
            else:
                try:
                    _usage_cost(usage, data["models"][batch["model"]], request["max_output_tokens"])
                except BudgetError as exc:
                    request.update(status="failed", error_type="invalid_usage")
                    batch.update(halted=True, halt_reason="invalid_usage")
                    error = exc
                else:
                    request.update(status="reconciled", usage={"prompt_tokens": usage["prompt_tokens"],
                                                               "completion_tokens": usage["completion_tokens"]})
            self._totals(data, credit)
            self._save(data)
            if error:
                raise error

    def halt(self, reason: str) -> None:
        if not isinstance(reason, str) or not reason or len(reason) > 100 or not all(c.isalnum() or c in "_-" for c in reason):
            raise BudgetError("Invalid halt reason")
        with self._locked():
            data, batch, credit, _ = self._load()
            batch.update(halted=True, halt_reason=reason)
            self._totals(data, credit)
            self._save(data)

    def reconcile(self, request_id: str, usage: dict) -> None:
        self._finish(request_id, usage=usage)

    def fail(self, request_id: str, error_type: str, *, halt: bool = False) -> None:
        if not isinstance(error_type, str) or not error_type or len(error_type) > 100 or not all(c.isalnum() or c in "_-" for c in error_type):
            raise BudgetError("Invalid error type")
        self._finish(request_id, error_type=error_type, halt=halt)

class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise LLMError("Model HTTP redirects are disabled")


_HTTP = urllib.request.build_opener(_NoRedirect())
LOCAL_URLS = {f"http://{host}:11434/v1/chat/completions" for host in ("localhost", "127.0.0.1")}
OPENAI_URL = "https://api.openai.com/v1/chat/completions"


def _post(url: str, payload: dict, headers: dict, timeout: float, retries: int | None = None,
          *, budget: CostLedger | None = None, role: str = "AGENT") -> dict:
    local = url in LOCAL_URLS
    if not local and (url != OPENAI_URL or budget is None):
        raise BudgetError("Remote calls require an approved direct-OpenAI text batch; other providers/audio are blocked")
    if local:
        budget = None  # Local roles share runtime limits, but do not spend OpenAI credit.
    token_key = "max_tokens" if local else "max_completion_tokens"
    cap = payload.get(token_key)
    if type(cap) is not int or not 1 <= cap <= 1200:
        raise BudgetError("Output token cap must be an integer from 1 to 1200")
    allowed = {"model", "messages", "temperature", token_key, "tools", "response_format"}
    allowed |= {"reasoning_effort"} if local else {"service_tier", "n"}
    if set(payload) - allowed:
        raise BudgetError("Only bounded text Chat Completions fields are allowed")
    if not local and (payload.get("service_tier") != "default" or payload.get("n") != 1):
        raise BudgetError("Paid requests require standard tier and n=1")
    if not isinstance(payload.get("messages"), list) or any(
            not isinstance(m, dict) or set(m) - {"role", "content", "tool_calls", "tool_call_id"}
            or not (isinstance(m.get("content"), str) or m.get("content") is None)
            for m in payload["messages"]):
        raise BudgetError("Only text messages are allowed; audio and images are blocked")
    if any(not isinstance(t, dict) or t.get("type") != "function" for t in payload.get("tools", [])):
        raise BudgetError("Only local function tools are allowed, not separately billed hosted tools")
    body = json.dumps(payload).encode("utf-8")
    if len(body) > 256000:
        raise BudgetError("Request exceeds the hard 256000-byte text limit")
    retry_limit = budget.limits["max_retries"] if budget is not None else 0
    retries = retry_limit if retries is None else retries
    if type(retries) is not int or not 0 <= retries <= retry_limit:
        raise BudgetError("Retry count exceeds batch limits")
    for attempt in range(retries + 1):
        reservation = (budget.reserve(payload["model"], cap, len(body), role, attempt)
                       if budget is not None else None)
        request = urllib.request.Request(url, data=body, method="POST",
                                         headers={"Content-Type": "application/json", **headers})
        try:
            with _HTTP.open(request, timeout=min(timeout, 30.0)) as response:
                data = json.loads(response.read().decode("utf-8"))
            if budget is not None:
                if not isinstance(data, dict):
                    budget.fail(reservation, "MalformedResponse", halt=True)
                    raise BudgetError("Non-object response; batch halted")
                if data.get("service_tier") != "default" or data.get("model") != payload["model"]:
                    budget.fail(reservation, "UnexpectedModelOrServiceTier", halt=True)
                    raise BudgetError("Unexpected response model/service tier; batch halted")
                budget.reconcile(reservation, data.get("usage"))
            return data
        except BudgetError:
            raise
        except Exception as err:
            retryable = (isinstance(err, (urllib.error.URLError, TimeoutError))
                         and not isinstance(err, urllib.error.HTTPError)) or (
                isinstance(err, urllib.error.HTTPError) and err.code in (429, 500, 502, 503, 529))
            if budget is not None:
                budget.fail(reservation, type(err).__name__, halt=not retryable)
            if retryable and attempt < retries:
                time.sleep(2 ** attempt)
                continue
            raise LLMError(f"Model request failed ({type(err).__name__}); uncertain usage remains reserved") from None
    raise LLMError("unreachable")


class OpenAICompatibleClient:
    def __init__(self, model: str, base_url: str, api_key: str | None = None,
                 timeout: float = 30.0, extra: dict | None = None,
                 budget: CostLedger | None = None, role: str = "AGENT"):
        self.model, self.base_url, self.api_key = model, base_url.rstrip("/"), api_key
        self.timeout, self.extra = timeout, extra or {}
        self.budget, self.role = budget, role

    @staticmethod
    def to_wire(messages: list[dict]) -> list[dict]:
        wire = []
        for m in messages:
            if m["role"] == "assistant" and m.get("tool_calls"):
                wire.append({"role": "assistant", "content": m.get("content") or None,
                             "tool_calls": [{"id": c["id"], "type": "function",
                                             "function": {"name": c["name"],
                                                          "arguments": json.dumps(c["arguments"])}}
                                            for c in m["tool_calls"]]})
            elif m["role"] == "tool":
                wire.append({"role": "tool", "tool_call_id": m["tool_call_id"], "content": m["content"]})
            else:
                wire.append({"role": m["role"], "content": m["content"]})
        return wire

    @staticmethod
    def from_wire(data: dict) -> Completion:
        message = data["choices"][0]["message"]
        calls = []
        for i, c in enumerate(message.get("tool_calls") or []):
            raw = c["function"].get("arguments") or "{}"
            try:
                args = json.loads(raw) if isinstance(raw, str) else raw
            except json.JSONDecodeError:
                args = {"_unparsed": raw}
            calls.append({"id": c.get("id") or f"call_{i}", "name": c["function"]["name"], "arguments": args})
        usage = data.get("usage") or {}
        return Completion(content=message.get("content") or "", tool_calls=calls,
                          usage={"input_tokens": usage.get("prompt_tokens", 0),
                                 "output_tokens": usage.get("completion_tokens", 0)})

    def complete(self, messages, tools=None, temperature=0.0, max_tokens=800, json_mode=False) -> Completion:
        direct_openai = self.base_url == "https://api.openai.com/v1"
        token_key = "max_completion_tokens" if direct_openai else "max_tokens"
        payload = {"model": self.model, "messages": self.to_wire(messages),
                   "temperature": temperature, token_key: max_tokens, **self.extra}
        if direct_openai:
            payload.update(service_tier="default", n=1)
        if tools:
            payload["tools"] = [{"type": "function", "function": t} for t in tools]
        if json_mode:
            payload["response_format"] = {"type": "json_object"}
        headers = {"Authorization": f"Bearer {self.api_key}"} if self.api_key else {}
        start = time.perf_counter()
        result = self.from_wire(_post(f"{self.base_url}/chat/completions", payload, headers, self.timeout,
                                      budget=self.budget, role=self.role))
        result.latency_s = time.perf_counter() - start
        return result


